 public void CommitPending(){if(SelectedIndex<0)return;if(regions[SelectedIndex].CoordinateSpace==RoiCoordinateSpace.Normalized)throw new InvalidOperationException("请先获取输入图像，才能编辑归一化ROI。");var r=regions[SelectedIndex];foreach(var (key,input) in inputs){if(!double.TryParse(input.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var value)||!double.IsFinite(value))throw new InvalidDataException("ROI包含无效数值："+key);r=RoiParameterTemplates.Put(r,key,value);}if(r.Kind==RoiKind.Polygon&&polygonInputs.Count>0){var points=r.Vertices!.ToArray();foreach(var pair in polygonInputs){if(!double.TryParse(pair.Value.X.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var x)||!double.TryParse(pair.Value.Y.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var y)||!double.IsFinite(x)||!double.IsFinite(y)||Math.Abs(x)>30000||Math.Abs(y)>30000)throw new InvalidDataException("多边形点坐标无效。");points[pair.Key]=new(x,y);}r=r with{Vertices=points};}RoiGeometry.ValidateForEditor(regions.Select((v,i)=>i==SelectedIndex?r:v).ToArray(),capability);var previous=regions[SelectedIndex];bool changed=(previous with{Vertices=null})!=(r with{Vertices=null})||!(previous.Vertices??[]).SequenceEqual(r.Vertices??[]);regions[SelectedIndex]=r;surface.InvalidateVisual();if(changed)GeometryCommitted?.Invoke(this,EventArgs.Empty);}
