  }
  public void Update(Point p){if(!active)return;double dx=p.X-start.X,dy=p.Y-start.Y;if(draft is not null){draft=draft with{CenterX=(start.X+p.X)/2,CenterY=(start.Y+p.Y)/2,Width=Math.Max(.001,Math.Abs(dx)),Height=Math.Max(.001,Math.Abs(dy)),Radius=Math.Max(.001,Math.Sqrt(dx*dx+dy*dy)/2),InnerRadius=0};if(RoiWpfGeometry.IsRadial(draft.Kind)){draft=draft with{CenterX=start.X,CenterY=start.Y,Radius=Math.Max(.001,Math.Sqrt(dx*dx+dy*dy))};if(draft.Kind is RoiKind.Annulus or RoiKind.SectorRing)draft=draft with{InnerRadius=draft.Radius/2};if(draft.Kind is RoiKind.Sector or RoiKind.OverSector)draft=draft with{Shape=new(StartAngle:0,SweepAngle:90)};}if(RoiWpfGeometry.IsLine(draft.Kind))draft=draft with{CenterX=start.X,CenterY=start.Y,Shape=new(EndX:p.X,EndY:p.Y,CaliperCount:6),Radius=Math.Max(.001,(p-start).Length)};if(draft.Kind==RoiKind.MatrixCircle)draft=draft with{Radius=Math.Min(draft.Width,draft.Height)/4,InnerRadius=Math.Min(draft.Width,draft.Height)/6};if(draft.Kind==RoiKind.LineCaliper)draft=draft with{Shape=RoiGeometry.Parameters(draft) with{CaliperHeight=(p-start).Length/7}};if(draft.Kind==RoiKind.SectorCaliper)draft=draft with{Shape=RoiGeometry.Parameters(draft) with{CaliperHeight=draft.Radius/4}};if(draft.Kind==RoiKind.CircleCaliper)draft=draft with{Shape=new(CaliperCount:30,CaliperHeight:draft.Radius/3)};}else if(original is {} r){RoiDocument next;if(handle<0)next=r with{CenterX=r.CenterX+dx,CenterY=r.CenterY+dy,Vertices=r.Vertices?.Select(v=>new Point2(v.X+dx,v.Y+dy)).ToArray(),Shape=RoiWpfGeometry.IsLine(r.Kind)?RoiGeometry.Parameters(r) with{EndX=RoiGeometry.Parameters(r).EndX+dx,EndY=RoiGeometry.Parameters(r).EndY+dy}:r.Shape};else if(TryCaliperDrag(r,p,out next)){}else if(RoiWpfGeometry.IsLine(r.Kind)){var shape=RoiGeometry.Parameters(r);next=handle==0?r with{CenterX=p.X,CenterY=p.Y}:r with{Shape=shape with{EndX=p.X,EndY=p.Y}};if(r.Kind==RoiKind.SectorCaliper){var end=RoiGeometry.Parameters(next);double chord=(new Point(end.EndX,end.EndY)-new Point(next.CenterX,next.CenterY)).Length;next=next with{Radius=Math.Max(next.Radius,chord/2)};}}else if(r.Kind is RoiKind.Point or RoiKind.Coordinate)next=handle==0?r with{CenterX=p.X,CenterY=p.Y}:r with{AngleDegrees=Math.Atan2(p.Y-r.CenterY,p.X-r.CenterX)*180/Math.PI};else if(RoiWpfGeometry.IsRadial(r.Kind)){double radius=(p-new Point(r.CenterX,r.CenterY)).Length;next=handle==1&&r.Kind is (RoiKind.Annulus or RoiKind.SectorRing)?r with{InnerRadius=Math.Clamp(radius,0,r.Radius-.001)}:r with{Radius=Math.Max(radius,r.InnerRadius+.001)};if(r.Kind is RoiKind.Sector or RoiKind.OverSector&&handle>0){var shape=RoiGeometry.Parameters(r);double angle=Math.Atan2(p.Y-r.CenterY,p.X-r.CenterX)*180/Math.PI;next=handle==1?r with{Shape=shape with{StartAngle=angle}}:r with{Shape=shape with{SweepAngle=Math.Max(.001,(angle-shape.StartAngle+360)%360)}};}}else if(r.Kind==RoiKind.Polygon){var points=r.Vertices!.ToArray();points[handle]=new(p.X,p.Y);next=r with{Vertices=points};}else if(handle==4)next=r with{AngleDegrees=Math.Atan2(p.Y-r.CenterY,p.X-r.CenterX)*180/Math.PI+90};else{var local=new RotateTransform(-r.AngleDegrees,r.CenterX,r.CenterY).Transform(p);var anchor=Handles(r)[(handle+2)%4];anchor=new RotateTransform(-r.AngleDegrees,r.CenterX,r.CenterY).Transform(anchor);var center=new RotateTransform(r.AngleDegrees,r.CenterX,r.CenterY).Transform(new Point((local.X+anchor.X)/2,(local.Y+anchor.Y)/2));next=r with{CenterX=center.X,CenterY=center.Y,Width=Math.Max(.001,Math.Abs(local.X-anchor.X)),Height=Math.Max(.001,Math.Abs(local.Y-anchor.Y))};}owner.regions[owner.SelectedIndex]=next;}InvalidateVisual();}
  bool TryCaliperDrag(RoiDocument r,Point p,out RoiDocument result){result=r;if(r.Kind is not (RoiKind.LineCaliper or RoiKind.CircleCaliper or RoiKind.SectorCaliper))return false;int first=r.Kind==RoiKind.CircleCaliper?1:2;if(handle<first)return false;var shape=RoiGeometry.Parameters(r);if(r.Kind==RoiKind.SectorCaliper&&handle==5){var midpoint=new Point((r.CenterX+shape.EndX)/2,(r.CenterY+shape.EndY)/2);var v=p-midpoint;double length=v.Length;if(length==0)return true;var old=start-midpoint;double half=(new Point(shape.EndX,shape.EndY)-new Point(r.CenterX,r.CenterY)).Length/2;double radius=(half*half+length*length)/(2*length);result=r with{Radius=Math.Min(10000,radius),Shape=shape with{IsClockwise=old*v<0?!shape.IsClockwise:shape.IsClockwise,IsLargeArc=radius<length}};return true;}var caliper=RoiWpfGeometry.ActiveCaliper(r);var delta=p-caliper.Center;double angle=caliper.Angle*Math.PI/180,x=Math.Abs(delta.X*Math.Cos(angle)+delta.Y*Math.Sin(angle))*2,y=Math.Abs(-delta.X*Math.Sin(angle)+delta.Y*Math.Cos(angle))*2;double maxWidth=r.Kind==RoiKind.LineCaliper?Math.Max(1,Math.Min(500,2*(new Point(shape.EndX,shape.EndY)-new Point(r.CenterX,r.CenterY)).Length/(shape.CaliperCount+1))):500;double maxHeight=r.Kind==RoiKind.LineCaliper?30000:Math.Max(1,2*r.Radius);result=r with{Shape=shape with{CaliperWidth=handle==first||handle==first+2?Math.Clamp(x,1,maxWidth):shape.CaliperWidth,CaliperHeight=handle==first+1||handle==first+2?Math.Clamp(y,r.Kind==RoiKind.LineCaliper?3:1,maxHeight):shape.CaliperHeight}};return true;}
  public void End(Point p){if(!active)return;Update(p);if(draft is not null&&(p-start).Length<.001){draft=null;active=false;InvalidateVisual();return;}if(draft is not null){RoiValidator.Validate(draft);owner.regions.Add(draft);if(owner.createNormalized)owner.normalizedIds.Add(draft.Id);draft=null;owner.DrawKind=null;owner.RefreshModes();owner.RefreshList(owner.regions.Count-1);}if(original is not null&&owner.SelectedIndex>=0)RoiValidator.Validate(owner.regions[owner.SelectedIndex]);active=false;original=null;owner.RefreshFields();owner.GeometryCommitted?.Invoke(owner,EventArgs.Empty);InvalidateVisual();}
  public void CompletePolygon(){if(polygon.Count<3)throw new InvalidOperationException("多边形至少需要3个点");if(owner.regions.Count>=owner.capability.Maximum)throw new InvalidOperationException("ROI数量达到工具上限");var r=new RoiDocument(Guid.NewGuid().ToString("N"),RoiKind.Polygon,0,0,Vertices:polygon.ToArray()){Exclusion=owner.DrawExclusion};RoiValidator.Validate(r);owner.regions.Add(r);if(owner.createNormalized)owner.normalizedIds.Add(r.Id);polygon.Clear();owner.DrawKind=null;owner.RefreshModes();owner.RefreshList(owner.regions.Count-1);owner.GeometryCommitted?.Invoke(owner,EventArgs.Empty);InvalidateVisual();}
  public void UndoPolygonPoint(){if(polygon.Count>0)polygon.RemoveAt(polygon.Count-1);InvalidateVisual();}
  public void CancelAll(){Cancel();polygon.Clear();owner.DrawKind=null;owner.RefreshModes();}
  public void Cancel(){if(active&&original is not null&&owner.SelectedIndex>=0)owner.regions[owner.SelectedIndex]=original;draft=null;original=null;active=false;InvalidateVisual();}
  protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e){base.OnMouseLeftButtonDown(e);Focus();try{owner.CommitPending();if(owner.DrawKind==RoiKind.Polygon&&e.ClickCount==2){CompletePolygon();e.Handled=true;return;}Press(ToImage(e.GetPosition(this)));if(!active&&owner.DrawKind is null&&Image is not null){panning=true;panStart=e.GetPosition(this);panOffset=offset;}if(active||panning||owner.DrawKind==RoiKind.Polygon)CaptureMouse();e.Handled=true;}catch(Exception error){owner.error.Text=error.Message;}}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(active)Update(ToImage(e.GetPosition(this)));else if(panning){var delta=e.GetPosition(this)-panStart;offset=panOffset+delta;InvalidateVisual();}}
  protected override void OnMouseLeftButtonUp(MouseButtonEventArgs e){base.OnMouseLeftButtonUp(e);try{Release(ToImage(e.GetPosition(this)));panning=false;}catch(Exception error){owner.error.Text=error.Message;Cancel();}finally{if(owner.DrawKind!=RoiKind.Polygon&&!(active&&draft is {} pending&&RoiWpfGeometry.IsLine(pending.Kind)))ReleaseMouseCapture();}}
  protected override void OnLostMouseCapture(MouseEventArgs e){base.OnLostMouseCapture(e);panning=false;CancelAll();owner.RefreshFields();}
  protected override void OnMouseWheel(MouseWheelEventArgs e){ZoomAt(e.GetPosition(this),1+Math.Round(e.Delta/120.0,MidpointRounding.AwayFromZero)*0.5);e.Handled=true;}
  protected override void OnKeyDown(System.Windows.Input.KeyEventArgs e){base.OnKeyDown(e);if(e.Key==Key.Escape){CancelAll();ReleaseMouseCapture();owner.RefreshFields();e.Handled=true;}else if(e.Key==Key.Delete){owner.DeleteSelected();e.Handled=true;}else if(e.Key is Key.Left or Key.Right or Key.Up or Key.Down&&owner.SelectedIndex>=0){var r=owner.regions[owner.SelectedIndex];double dx=e.Key==Key.Left?-1:e.Key==Key.Right?1:0,dy=e.Key==Key.Up?-1:e.Key==Key.Down?1:0;var shape=RoiGeometry.Parameters(r);owner.regions[owner.SelectedIndex]=r with{CenterX=r.CenterX+dx,CenterY=r.CenterY+dy,Vertices=r.Vertices?.Select(v=>new Point2(v.X+dx,v.Y+dy)).ToArray(),Shape=RoiWpfGeometry.IsLine(r.Kind)?shape with{EndX=shape.EndX+dx,EndY=shape.EndY+dy}:r.Shape};owner.RefreshFields();owner.GeometryCommitted?.Invoke(owner,EventArgs.Empty);e.Handled=true;}else if(e.Key==Key.C&&Keyboard.Modifiers==ModifierKeys.Control){owner.CopySelected();e.Handled=true;}}
